from pathlib import Path

path = Path("components/calculators/CalculatorEngine.tsx")
text = path.read_text()
old = '''      {embedMode ? null : (<section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm md:p-8"><h2 className="text-2xl font-bold text-slate-900">{locale === "ko" ? "이 계산기 공유하기" : "Embed this calculator"}</h2><p className="mt-3 text-sm leading-7 text-slate-600 md:text-base">{locale === "ko" ? "아래 코드를 블로그나 웹사이트에 넣으면 이 계산기를 간단히 공유할 수 있습니다." : "Copy this iframe code to place the calculator on your blog or website."}</p><div className="mt-5 overflow-x-auto rounded-2xl bg-slate-950 p-4"><code className="whitespace-pre text-sm leading-7 text-slate-100">{embedCode}</code></div><button type="button" onClick={copyEmbedCode} className="mt-4 inline-flex rounded-2xl bg-blue-600 px-5 py-3 text-sm font-semibold text-white transition hover:bg-blue-500">{copied ? (locale === "ko" ? "복사 완료" : "Copied") : (locale === "ko" ? "임베드 코드 복사" : "Copy embed code")}</button></section>)}'''
new = '''      {embedMode ? null : (<details className="group rounded-2xl border border-slate-200 bg-slate-50 px-5 py-4"><summary className="cursor-pointer list-none text-sm font-semibold text-slate-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2">{locale === "ko" ? "웹사이트에 이 계산기 추가" : "Add this calculator to a website"}<span aria-hidden="true" className="ml-2 inline-block transition group-open:rotate-180">⌄</span></summary><div className="mt-4 border-t border-slate-200 pt-4"><p className="text-sm leading-7 text-slate-600">{locale === "ko" ? "블로그나 웹사이트를 운영하신다면 아래 코드를 복사해 계산기를 삽입할 수 있습니다." : "If you run a blog or website, copy the code below to embed this calculator."}</p><div className="mt-4 overflow-x-auto rounded-2xl bg-slate-950 p-4"><code className="whitespace-pre text-sm leading-7 text-slate-100">{embedCode}</code></div><button type="button" onClick={copyEmbedCode} className="mt-4 inline-flex rounded-2xl bg-blue-600 px-5 py-3 text-sm font-semibold text-white transition hover:bg-blue-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2">{copied ? (locale === "ko" ? "복사 완료" : "Copied") : (locale === "ko" ? "삽입 코드 복사" : "Copy embed code")}</button></div></details>)}'''
if old not in text:
    raise SystemExit("embed section target not found")
text = text.replace(old, new)
path.write_text(text)
print("phase 2 embed disclosure applied")
